<?php
namespace App\Filament\Admin\Resources\Policies\Pages;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\Policies\PolicyResource;use App\Models\{CertificateTemplate,StickerStock};use Filament\Actions\Action;use Filament\Forms\Components\{DateTimePicker,KeyValue,Select,TextInput,Textarea};use Filament\Resources\Pages\ViewRecord;final class ViewPolicy extends ViewRecord{protected static string $resource=PolicyResource::class;protected function getHeaderActions():array{return[\App\Filament\Shared\Actions\PolicyActions::group(),Action::make('issueCertificate')->label('Issue certificate')->icon('heroicon-o-qr-code')->visible(fn()=>$this->record->status==='ACTIVE')->schema([Select::make('certificate_template_id')->options(fn()=>CertificateTemplate::where('status','ACTIVE')->pluck('code','id'))->required()->searchable(),TextInput::make('serial_number')->required()->maxLength(100),TextInput::make('document_hash')->required()->length(64),Select::make('sticker_serial_number')->options(fn()=>StickerStock::where(['carrier_id'=>$this->record->carrier_id,'custodian_tenant_id'=>$this->record->tenant_id,'status'=>'IN_STOCK'])->pluck('serial_number','serial_number'))->searchable()])->action(function(array$d){if(ServiceValidation::run(fn()=>app(\App\Application\Certificates\CertificateService::class)->issue($this->record,CertificateTemplate::findOrFail($d['certificate_template_id']),$d,auth()->user()))===null)return;})];}}
